  document.body.append(transitionDebugToggle);
  transitionDebugOverlay.className = "preview-transition-debug";
  transitionDebugOverlay.hidden = true;
  transitionDebugOverlay.setAttribute("aria-hidden", "true");
  transitionDebugOverlay.style.position = "fixed";
  transitionDebugOverlay.style.right = "16px";
  transitionDebugOverlay.style.bottom = "16px";
  transitionDebugOverlay.style.zIndex = "5000";
  transitionDebugOverlay.style.width = "min(420px, calc(100vw - 32px))";
