  transitionDebugOverlay.style.overflow = "auto";
  transitionDebugOverlay.style.padding = "12px 14px";
  transitionDebugOverlay.style.borderRadius = "16px";
  transitionDebugOverlay.style.border = "1px solid rgba(37, 99, 235, 0.28)";
  transitionDebugOverlay.style.background = "rgba(255,255,255,0.98)";
  transitionDebugOverlay.style.boxShadow = "0 18px 44px rgba(15,23,42,0.18)";
  transitionDebugOverlay.style.backdropFilter = "blur(16px)";
  transitionDebugOverlay.style.whiteSpace = "pre-wrap";
  transitionDebugOverlay.style.font = "12px/1.45 ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace";
  transitionDebugOverlay.style.color = "#0f172a";
  document.body.append(transitionDebugOverlay);

  function formatTransitionDebugRect(rect) {
    if (!rect) {
      return "none";
    }
    const left = Math.round(Number(rect.left || 0));
    const top = Math.round(Number(rect.top || 0));
    const width = Math.round(Number(rect.width || 0));
    const height = Math.round(Number(rect.height || 0));
    return `${left},${top} ${width}x${height}`;
  }

  function isCurrentUserAdmin() {
    return String(window.uxBridgeUser?.role || "").trim().toLowerCase() === "admin";
  }

  function renderTransitionDebugOverlay() {
    if (!(transitionDebugOverlay instanceof HTMLElement)) {
      return;
    }
    const isAdmin = isCurrentUserAdmin();
    const info = state.transitionDebugInfo;
    if (transitionDebugToggle instanceof HTMLElement) {
      const shouldShowToggle = Boolean(state.previewMode && isAdmin && info);
      transitionDebugToggle.hidden = !shouldShowToggle;
      transitionDebugToggle.setAttribute("aria-hidden", shouldShowToggle ? "false" : "true");
      transitionDebugToggle.setAttribute("aria-expanded", state.transitionDebugExpanded ? "true" : "false");
      transitionDebugToggle.textContent = state.transitionDebugExpanded ? "Hide debug" : "Debug";
    }
    if (!state.previewMode || !isAdmin || !info || !state.transitionDebugExpanded) {
      transitionDebugOverlay.hidden = true;
      transitionDebugOverlay.setAttribute("aria-hidden", "true");
      transitionDebugOverlay.textContent = "";
      return;
    }
    const lines = [
      "TRANSITION DEBUG",
      `transition: ${String(info.transition || "")}`,
      `matching: ${info.animateMatchingLayers ? "on" : "off"}`,
      `easing: ${String(info.easing || "")}`,
      `duration: ${String(info.duration || "")}ms`,
      `primary keys: ${Array.isArray(info.primaryMatchKeys) && info.primaryMatchKeys.length ? info.primaryMatchKeys.join(", ") : "none"}`,
      `direct matches: ${Number(info.directMatchCount || 0)}`,
      `inferred matches: ${Number(info.inferredMatchCount || 0)}`,
      `final matches: ${Number(info.finalMatchCount || 0)}`,
    ];
    if (Array.isArray(info.directMatches) && info.directMatches.length) {
      lines.push("");
      lines.push("DIRECT:");
      info.directMatches.forEach((match, index) => {
        lines.push(
          `${index + 1}. ${String(match.key || "")}\n   out: ${formatTransitionDebugRect(match.outgoingRect)}\n   in:  ${formatTransitionDebugRect(match.incomingRect)}\n   live: ${match.hasLiveIncomingNode ? "yes" : "no"}`,
        );
      });
    }
    if (Array.isArray(info.primaryCandidateDebug) && info.primaryCandidateDebug.length) {
      info.primaryCandidateDebug.forEach((entry, entryIndex) => {
        lines.push("");
        lines.push(`CANDIDATES ${entryIndex + 1}:`);
        if (entry.key) {
          lines.push(` key: ${String(entry.key)}`);
        }
        if (entry.signature) {
          lines.push(` sig: ${String(entry.signature).slice(0, 96)}`);
        }
        if (entry.keyLookupRect) {
          lines.push(` key rect: ${formatTransitionDebugRect(entry.keyLookupRect)}`);
        } else {
          lines.push(" key rect: none");
        }
        if (entry.signatureLookupRect) {
          lines.push(` sig rect: ${formatTransitionDebugRect(entry.signatureLookupRect)}`);
        } else {
          lines.push(" sig rect: none");
        }
        if (!Array.isArray(entry.candidates) || !entry.candidates.length) {
          lines.push(" no identity candidates");
        } else {
          entry.candidates.slice(0, 5).forEach((candidate, candidateIndex) => {
            lines.push(`${candidateIndex + 1}. score:${Math.round(Number(candidate.score) || 0)} key:${String(candidate.key || "none")}`);
            if (candidate.label) {
              lines.push(`   label: ${String(candidate.label)}`);
            }
            if (candidate.signature) {
              lines.push(`   sig: ${String(candidate.signature).slice(0, 96)}`);
            }
            lines.push(`   rect: ${formatTransitionDebugRect(candidate.rect)}`);
          });
        }
        if (!Array.isArray(entry.textCandidates) || !entry.textCandidates.length) {
          lines.push(" no text candidates");
        } else {
          lines.push(" TEXT:");
          entry.textCandidates.slice(0, 5).forEach((candidate, candidateIndex) => {
            lines.push(`${candidateIndex + 1}. score:${Math.round(Number(candidate.score) || 0)} key:${String(candidate.key || "none")}`);
            if (candidate.label) {
              lines.push(`   label: ${String(candidate.label)}`);
            }
            if (candidate.signature) {
              lines.push(`   sig: ${String(candidate.signature).slice(0, 96)}`);
            }
            lines.push(`   rect: ${formatTransitionDebugRect(candidate.rect)}`);
          });
        }
      });
    }
    if (Array.isArray(info.finalMatches) && info.finalMatches.length) {
      lines.push("");
      lines.push("FINAL:");
      info.finalMatches.forEach((match, index) => {
        lines.push(
          `${index + 1}. ${String(match.key || "")}\n   out: ${formatTransitionDebugRect(match.outgoingRect)}\n   in:  ${formatTransitionDebugRect(match.incomingRect)}\n   travel: ${Math.round(Number(match.travel || 0))}\n   scaleDelta: ${Number(match.scaleDelta || 0).toFixed(3)}`,
        );
      });
    }
    transitionDebugOverlay.textContent = lines.join("\n");
    transitionDebugOverlay.hidden = false;
    transitionDebugOverlay.setAttribute("aria-hidden", "false");
    transitionDebugOverlay.style.bottom = "64px";
  }

