  const startLayerToolsHoverGrace = () => {
    if (state.layerToolsHoverGraceTimer) {
      window.clearTimeout(state.layerToolsHoverGraceTimer);
      state.layerToolsHoverGraceTimer = null;
    }
    state.layerToolsHoverGraceUntil = Date.now() + 240;
    state.layerToolsHoverGraceTimer = window.setTimeout(() => {
      state.layerToolsHoverGraceTimer = null;
      if (!state.layerToolsHoverActive && !state.activeLayerTool) {
        renderSelectedLayerTools();
      }
    }, 250);
    renderSelectedLayerTools();
  };

