          key,
          outgoingNode: outgoingNode || incomingNode.cloneNode(true),
          incomingNode: incomingNode.cloneNode(true),
          incomingLiveNode: incomingNode,
          outgoingHost: outgoingRoot,
          incomingHost: incomingRoot,
          outgoingRect,
          incomingRect,
          outgoingVisible,
          incomingVisible,
