      const dy = incomingRect.top - outgoingRect.top;
      const travel = Math.hypot(dx, dy);
      const scaleX = outgoingRect.width > 0 ? incomingRect.width / outgoingRect.width : 1;
      const scaleY = outgoingRect.height > 0 ? incomingRect.height / outgoingRect.height : 1;
