    const materialStandard = "cubic-bezier(0.4, 0, 0.2, 1)";
    const materialDecelerate = "cubic-bezier(0, 0, 0.2, 1)";
    const materialAccelerate = "cubic-bezier(0.4, 0, 1, 1)";
