      const transitionName = normalizePrototypeLinkTransition(options.transition);
      const animateMatchingLayers = normalizePrototypeLinkAnimateMatchingLayers(options.animateMatchingLayers);
      const animateMatchingLayersEasing = normalizePrototypeLinkAnimateMatchingLayersEasing(
        options.animateMatchingLayersEasing,
      );
      const animateMatchingLayersDuration = normalizePrototypeLinkAnimateMatchingLayersDuration(
        options.animateMatchingLayersDuration,
      );
