                      return `
                        <button type="button" class="preview-inspector__background-radial-handle preview-inspector__background-radial-handle--center" data-preview-background-angular-handle="center" data-tooltip="Center" style="left:${handles.center.x}%; top:${handles.center.y}%;" aria-label="Move angular gradient center"></button>
                      `;
